import {mechanism,soundTest,centerTrain} from './mechanism.js';
import {pieces,evaluate} from './drawer-logic.js';
import {pieceArt} from './piece-art.js';
import {doodle} from './art.js';
export function drawer(){return `<section class="drawer-page"><a class="back-small" href="#/caderno">← Voltar ao caderno</a><div class="drawer-heading"><div><span class="eyebrow">EXPERIMENTO Nº 002 · PODE MEXER</span><h1>Uma coisa pequena.<br><em>E terminada.</em></h1></div><p>Uma encomenda esquecida.<br>Seis peças na gaveta.<br>E a tentação de usar todas.</p></div><div class="workbench"><aside class="order-paper"><span class="tape"></span><span class="eyebrow">O PEDIDO ERA SIMPLES</span><h2>Uma caixinha<br> para a porta.</h2><p>“Quando eu der corda, quero ouvir <strong>um único toque de sino</strong>. Depois, silêncio.”</p><div class="order-rule"></div><p class="handwriting">Separei umas peças.<br>Talvez mais do que precisava.<br>— L.</p><details><summary>Como mexer na bancada ↘</summary><p>Toque em uma peça para colocá-la. Toque outra vez para retirá-la. Dê corda e escute quantas vezes a caixinha toca. Quando achar que terminou, entregue a caixinha.</p></details><button class="hint-button" id="drawer-hint">Uma pista do Lior?</button><p id="drawer-hint-text" aria-live="polite"></p></aside><div class="machine-area"><div class="bench-meta"><span>ENSAIO <b id="attempt-number">00</b> / CAIXINHA DE PORTA</span><span>OUÇA. OBSERVE. TENTE.</span></div><div class="machine-window" id="machine-window">${mechanism()}</div><div class="test-note" role="status" aria-live="polite"><span id="test-label">AINDA NÃO TESTADA</span><p id="test-message">O que você colocaria aqui?</p></div><aside class="lior-whisper" aria-live="polite"><span>LIOR DEIXOU ESCRITO</span><p id="lior-comment">“Pode mexer. Só não confunda entusiasmo com uma peça necessária.”</p></aside><div class="bench-actions"><button class="ink-button" id="drawer-test">↻ Dar corda e testar</button><button class="deliver-button" id="drawer-deliver" disabled>Está pronto assim ↗</button></div><div class="bench-bottom"><span id="piece-count">0 peças na caixinha</span><button id="drawer-reset">Desmontar e recomeçar</button></div></div></div><aside class="lior-scrap"><span class="scrap-pin"></span><small>NO VERSO DE UM RECIBO</small><p>Eu sempre acho que falta alguma coisa.<br>Maela diz que às vezes sobra.</p><span>não jogar fora. — L.</span></aside><div class="parts-heading"><span class="eyebrow">A GAVETA DOS TALVEZ</span><span>Toque para colocar ou retirar.</span></div><div class="parts-tray">${[pieces[4],pieces[0],pieces[5],pieces[2],pieces[3],pieces[1]].map(p=>`<button class="part-card" data-piece="${p.id}" aria-pressed="false"><small>${p.tag}</small><span class="part-symbol" aria-hidden="true">${pieceArt(p.id)}</span><h2>${p.name}</h2><p>${p.hint}</p><span class="part-action">+ Colocar na caixinha</span></button>`).join('')}</div><button class="bench-return" id="bench-return">Voltar à bancada para testar ↑</button><section id="drawer-result" class="drawer-result" hidden tabindex="-1"><div class="reward-sky"><div class="reward-bird" aria-hidden="true">${doodle('bird')}</div></div><span class="eyebrow">ENCOMENDA CONCLUÍDA</span><h2>Você soube parar.</h2><p>A caixinha tocou uma vez. O pássaro, que estava olhando, achou que era a deixa dele.</p><p class="handwriting">“Eu teria colocado a outra roda.<br>Ainda bem que você chegou.”</p><span class="result-signature">L. BELLAMY</span><div><button id="drawer-again">Experimentar outra vez ↻</button><a href="#/">Voltar à oficina ↗</a></div></section><p class="experiment-footnote">Um pequeno experimento interativo da oficina. Explore no seu ritmo, sem tempo limite.</p></section>`}
export function mountDrawer({onComplete}={}){const root=document.querySelector('.drawer-page');if(!root)return ()=>{};const selected=new Set();let tested=null,hints=0,sound=true,audio,timer,busy=false,attempts=0;const controller=new AbortController();const $=s=>root.querySelector(s);const message=(label,text)=>{$('#test-label').textContent=label;$('#test-message').textContent=text};function update(){centerTrain(root,selected);root.querySelectorAll('[data-piece]').forEach(b=>{const on=selected.has(b.dataset.piece);b.setAttribute('aria-pressed',String(on));b.querySelector('.part-action').textContent=on?'− Retirar da caixinha':'+ Colocar na caixinha'});root.querySelectorAll('[data-machine]').forEach(g=>g.classList.toggle('installed',selected.has(g.dataset.machine)));$('#piece-count').textContent=`${selected.size} ${selected.size===1?'peça':'peças'} na caixinha`;$('#drawer-deliver').disabled=!tested?.ok||busy;$('#drawer-test').disabled=busy;root.querySelectorAll('[data-piece]').forEach(b=>b.disabled=busy)}function play(result){if(!sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume().catch(()=>{});soundTest(audio,result,selected.has('turbo'))}catch{sound=false}}function reset(){clearTimeout(timer);busy=false;selected.clear();tested=null;hints=0;attempts=0;$('#attempt-number').textContent='00';$('#lior-comment').textContent='“Recomeçar também conta. Tenho uma gaveta inteira que prova isso.”';$('#drawer-hint').textContent='Uma pista do Lior?';root.classList.remove('testing','finished','busy','balanced','loose','quiet','still');$('#drawer-result').hidden=true;$('#drawer-hint-text').textContent='';message('AINDA NÃO TESTADA','O que você colocaria aqui?');update()}
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.piece&&!busy){tested=null;selected.has(b.dataset.piece)?selected.delete(b.dataset.piece):selected.add(b.dataset.piece);root.classList.remove('finished');$('#drawer-result').hidden=true;message('PROJETO ALTERADO','Uma mudança, uma nova tentativa. Vamos testar?');update();return}if(b.id==='drawer-test'&&!busy){attempts++;tested=evaluate([...selected]);busy=true;root.classList.remove('testing','busy','balanced','loose','quiet','still');void root.offsetWidth;root.classList.add('testing',tested.state);message('TESTANDO…','A corda gira. Vamos ver o que acontece.');play(tested);update();timer=setTimeout(()=>{busy=false;root.classList.remove('testing');message(tested.ok?'FUNCIONA. PRECISA DE MAIS?':'ANOTAÇÃO DO TESTE',tested.message);const notes={still:'Você montou uma excelente natureza-morta. Vamos tentar fazê-la se mexer?',loose:'Boa notícia: alguma coisa aconteceu. Má notícia: só ela ficou sabendo.',quiet:'Está quase uma música. Falta a parte que a gente ouve.',busy:'Você também pensou “só mais uma pecinha”, não foi? Eu conheço essa cara.',balanced:selected.has('feather')?'A pena fica. Não ajuda em nada, mas a gente também merece um capricho.':'Eu teria continuado mexendo. Você talvez seja melhor nisso que eu.'};$('#lior-comment').textContent='“'+notes[tested.state]+'”';$('#attempt-number').textContent=String(attempts).padStart(2,'0');update()},1500)}if(b.id==='drawer-deliver'&&tested?.ok&&!busy){if(onComplete){onComplete();return}root.classList.add('finished');$('#drawer-result').hidden=false;$('#drawer-result').focus({preventScroll:true});$('#drawer-result').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});message('ENCOMENDA ENTREGUE','Um toque, e nada além do que precisava.');b.disabled=true;try{localStorage.setItem('lior-drawer-finished','true')}catch{}}if(b.id==='bench-return'){$('.machine-area').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});$('#drawer-test').focus({preventScroll:true})}if(b.id==='drawer-hint'){const lines=['Leia o pedido outra vez. Eu costumo me perder justamente nessa parte.','Quem guarda o impulso? Quem leva adiante? Quem responde? Três perguntas.','Uma mola para guardar a força, uma roda para levá-la, um sino para responder. Se ouvir duas batidas, veja qual peça está repetindo o movimento.'];$('#drawer-hint-text').textContent=lines[Math.min(hints++,2)];b.textContent=hints<3?'Virar outro bilhete ↗':'Reler o último bilhete'}if(b.id==='drawer-reset'||b.id==='drawer-again'){reset();$('#drawer-test').focus();$('.machine-area').scrollIntoView({behavior:'smooth',block:'center'})}},{signal:controller.signal});update();return ()=>{controller.abort();clearTimeout(timer);audio?.close()}}
